        let before = e.audit().len();

        let out = e.merge("feature").await.unwrap();
        assert_eq!(out["status"], "conflict");

        let audit = e.audit();
        assert_eq!(audit.len(), before + 1);
        let last = audit.last().unwrap();
        assert_eq!(last.op, "git.merge");
