        assert_eq!(actions, ["pick", "pick", "pick", "pick"]);
        let shas: Vec<&str> =
            todo.as_array().unwrap().iter().map(|t| t["sha"].as_str().unwrap()).collect();
        assert_eq!(shas, f.iter().map(String::as_str).collect::<Vec<_>>());
