        let before_audit = e.audit();
        let before_bytes = e.bytes_written();

        let err = reset(&e, json!({"target_ref": "nosuchref", "mode": "hard"})).await.unwrap_err();

        assert_eq!(err.code, code::NOT_FOUND, "{err:?}");
